def ahi_table(part):
    rows = []
    for r in SPL[part]:
        a, b = SPAN[r]; sl = np.isin(STG[a:b], ["N1", "N2", "N3", "R"]); sh = max(sl.sum() * 30 / 3600, 1e-3)
        rows.append(dict(rec=r, true=META.loc[r, "ahi"], pred=k_ev * ((P[a:b].argmax(1) > 0) & sl).sum() / sh))
    return pd.DataFrame(rows).set_index("rec")

def ahi_table(part):
    rows = []
    for r in SPL[part]:
        a, b = SPAN[r]
        sl = np.isin(STG[a:b], ["N1", "N2", "N3", "R"])
        sh = max(sl.sum() * 30 / 3600, 1e-3)
        rows.append(dict(
            rec=r,
            true=META.loc[r, "ahi"],
            pred=k_ev * ((P[a:b].argmax(1) > 0) & sl).sum() / sh,
        ))
    return pd.DataFrame(rows).set_index("rec")

def agree(t, col):
    d = t[col] - t.ref
    return dict(pearson=stats.pearsonr(t.ref, t[col])[0], spearman=stats.spearmanr(t.ref, t[col])[0], bias=d.mean(),
                loa_lo=d.mean() - 1.96 * d.std(), loa_hi=d.mean() + 1.96 * d.std(), MAE=d.abs().mean(),
                severity_acc=np.mean(sev(t.ref) == sev(t[col])), severity_kw=cohen_kappa_score(sev(t.ref), sev(t[col]), weights="quadratic"))
